<script setup lang="ts">
// Router query attributes are business filters, never the AppPage loading state.
defineOptions({inheritAttrs:false})
import {ref,onMounted} from 'vue';import {onShow} from '@dcloudio/uni-app';import AppPage from '../AppPage.vue';import AppNavbar from '@/components/AppNavbar.vue';import AppTabbar from '@/components/AppTabbar.vue';import BaseCard from '@/components/BaseCard.vue';import AppButton from '@/components/AppButton.vue';import StatusTag from '@/components/StatusTag.vue';import AppIcon from '@/components/AppIcon.vue';import SearchBar from '@/components/SearchBar.vue';import {merchantTabItems} from '@/config/navigation';import Stage1ProductImage from './Stage1ProductImage.vue';import Stage1Field from './Stage1Field.vue';import Stage1Status from './Stage1Status.vue';import {useStage1Page} from '../../services/use-stage1-page';import {stage1Service,label,amount} from '../../services/stage1';import type {Data,Page} from '../../services/stage1'
const props=defineProps<{query?:Data}>(),p=useStage1Page('goods-list'),{error,busy,loading,pending}=p,records=ref<Data[]>([]),total=ref(0),page=ref(1),search=ref(''),status=ref(props.query?.status||''),marketStatus=ref(props.query?.marketStatus||''),stockState=ref(props.query?.stockState||''),forced=ref(props.query?.forced||''),saleability=ref(props.query?.saleability||'')
function load(){return p.read(()=>stage1Service.read<Page<Data>>('/goods',{pageNumber:page.value,pageSize:20,search:search.value||undefined,status:status.value||undefined,marketStatus:marketStatus.value||undefined,stockState:stockState.value||undefined,forced:forced.value||undefined,saleability:saleability.value||undefined}),v=>{records.value=v.records;total.value=v.total})}
function edit(id?:string){uni.navigateTo({url:'/pages/product/editor/index'+(id?'?id='+id:'')})}
async function command(row:Data,action:string){const yes=await uni.showModal({title:action==='unlist'?'下架此商品？':'申请上架此商品？',content:action==='list'?'上架仅改变销售状态，实际可售仍取决于库存、资格和履约条件。':'下架后停止新增销售，保留历史资料。'});if(!yes.confirm)return;await p.write(()=>p.command('/goods/'+row.id+'/'+action,{expectedVersion:row.version}),()=>{return load()})}
onMounted(load);onShow(()=>{if(!pending.value)return load()})
</script>
<template><AppPage :status="loading&&!records.length?'loading':'ready'"><template #navbar><AppNavbar title="经营" compact show-user/></template><view class="s1-products stack"><Stage1Status :error="error" :pending="pending" :busy="busy" @recover="p.recover(load)" @retry="p.retry(load)" @abandon="p.abandon(load)"/><view class="s1-tools"><text>商品管理</text><AppButton class="s1-create" v-if="p.has('goods.write')" :disabled="pending" @click="edit()">新增商品</AppButton></view><SearchBar v-model="search" placeholder="搜索商品名称" clearable/><Stage1Field v-model="status" label="审核状态" type="select" :options="[{value:'',label:'全部'},{value:'DRAFT',label:'草稿'},{value:'SUBMITTED',label:'待审核'},{value:'APPROVED',label:'已通过'},{value:'REJECTED',label:'已驳回'}]"/><Stage1Field v-model="marketStatus" label="上架状态" type="select" :options="[{value:'',label:'全部'},{value:'UPPER',label:'已上架'},{value:'DOWN',label:'已下架'}]"/><Stage1Field v-model="stockState" label="库存状态" type="select" :options="[{value:'',label:'全部'},{value:'IN_STOCK',label:'有可售库存'},{value:'OUT_OF_STOCK',label:'缺货：启用SKU库存均为0'},{value:'INCOMPLETE',label:'SKU资料不完整'}]"/><Stage1Field v-model="saleability" label="当前可售状态" type="select" :options="[{value:'',label:'全部'},{value:'SALEABLE',label:'当前可售'},{value:'UNSALEABLE',label:'当前不可售'}]"/><Stage1Field v-model="forced" label="监管状态" type="select" :options="[{value:'',label:'全部'},{value:'true',label:'监管下架'},{value:'false',label:'未受管制'}]"/><AppButton variant="quiet" :loading="loading" @click="page=1;load()">查询</AppButton><template v-if="!error"><BaseCard v-for="row in records" :key="row.id" class="s1-product"><view class="s1-product__head" @click="edit(row.id)"><Stage1ProductImage :goods-id="row.id" :file-id="row.galleryFileIds?.[0]"/><view class="s1-product__main"><text class="s1-product__name">{{row.name||'未命名草稿'}}</text><view class="s1-tags"><StatusTag :tone="row.reviewStatus==='APPROVED'?'success':row.reviewStatus==='REJECTED'?'error':'pending'">{{label(row.reviewStatus)}}</StatusTag><StatusTag :tone="row.marketStatus==='UPPER'?'success':'disabled'">{{label(row.marketStatus)}}</StatusTag><StatusTag v-if="row.forcedOff" tone="error">监管下架</StatusTag></view></view></view><view class="s1-product__facts"><text class="s1-price">{{row.priceCent==null?'价格未填写':'¥ '+amount(row.priceCent)}}</text><text>{{row.stockState==='INCOMPLETE'?'SKU资料不完整':'当前库存 '+row.quantity}}</text></view><view class="s1-saleability"><text>模拟可售：{{row.mockSaleable?'满足条件':'不可售'}}</text><text>真实可售：{{row.realSaleable?'满足条件':'不可售'}}</text></view><text v-if="row.forcedReason" class="s1-error">{{row.forcedReason}}</text><text v-for="reason in row.saleabilityReasons" :key="reason" class="s1-meta">{{label(reason)}}</text><view class="s1-actions"><AppButton class="s1-action" variant="quiet" @click="edit(row.id)">{{p.has('goods.write')?'查看 / 编辑':'查看详情'}}</AppButton><AppButton class="s1-action" v-if="p.has('goods.publish')&&row.marketStatus==='UPPER'" variant="danger" :disabled="busy||pending" @click="command(row,'unlist')">下架</AppButton><AppButton class="s1-action" v-else-if="p.has('goods.publish')&&row.reviewStatus==='APPROVED'&&!row.forcedOff" :disabled="busy||pending" @click="command(row,'list')">上架</AppButton></view></BaseCard></template><BaseCard v-if="!loading&&!error&&!records.length"><text>暂无符合条件的商品。</text></BaseCard><view class="s1-pages"><AppButton variant="quiet" :disabled="page<=1||loading" @click="page--;load()">上一页</AppButton><text>{{page}} / {{Math.max(1,Math.ceil(total/20))}}</text><AppButton variant="quiet" :disabled="page*20>=total||loading" @click="page++;load()">下一页</AppButton></view></view><template #tabbar><AppTabbar :items="merchantTabItems" active-path="/pages/operation/index"/></template></AppPage></template>
<style scoped lang="scss">.s1-products{padding:$space-4 $page-gutter}.s1-tools{display:flex;justify-content:space-between;align-items:center;gap:$space-3}.s1-tools>text{font-size:20px;font-weight:700}.s1-create{width:auto}.s1-product{display:flex;flex-direction:column;gap:$space-3}.s1-product__head{display:flex;align-items:flex-start;gap:$space-3;min-height:72px}.s1-product__image{display:flex;align-items:center;justify-content:center;background:$color-group-bg;border-radius:$radius-md;flex:0 0 72px;height:72px}.s1-product__main{min-width:0;flex:1}.s1-product__name{font-size:16px;font-weight:700;line-height:1.5;overflow-wrap:anywhere}.s1-tags{display:flex;flex-wrap:wrap;gap:$space-1;margin-top:$space-2}.s1-product__facts,.s1-saleability{display:flex;justify-content:space-between;gap:$space-3;flex-wrap:wrap;font-size:14px}.s1-price{font-size:18px;color:$color-accent;font-weight:700}.s1-meta{font-size:13px;color:$color-text-secondary;line-height:1.6}.s1-error{color:$color-error;font-size:14px}.s1-actions,.s1-pages{display:flex;align-items:center;gap:$space-3}.s1-action,.s1-pages>button{flex:1}.s1-pages>text{white-space:nowrap;font-size:13px}:deep(.app-button){height:auto;min-height:44px;padding-top:$space-3;padding-bottom:$space-3;line-height:1.5}</style>
